  var structuralColumn=NewExtraGrid("StructuralColumn","Column Estimate","Reinforced Concrete Works",memberHeaders.Take(16).Concat(new[]{"Open ties parallel Width / set","Open ties parallel Depth / set"}).Concat(memberHeaders.Skip(16)).ToArray(),18,new Dictionary<int,string>{{3,"300"},{4,"300"},{5,"1"},{6,"16"},{7,"8"},{8,"12"},{9,"0"},{10,"10"},{11,"Spacing (mm)"},{12,"150"},{13,"0"},{14,"False"},{15,"0"}},"Rectangular tied RC column takeoff. Enter column height, section and approved main-bar count; select tie spacing or number of ties. Concrete = width × depth × height × quantity. Forms cover all four vertical faces. One closed main hoop per tie station. Enter optional open tie pieces parallel to Width and Depth; their cut shapes follow Column settings. Additional joint/confinement zones require their actual extent; they are not inferred from a note. Total end allowance is the approved additional length per main bar; do not duplicate bars already measured in beams or footings. Concrete routes to the Structural group; steel joins the project grade/diameter purchase plan.");ExtraChoice(structuralColumn.Grid,11,"Spacing (mm)","Number of ties","Spacing schedule");structuralColumn.Grid.Columns[12].HeaderText="Tie spacing mm / count / schedule";ExtraCheck(structuralColumn.Grid,14);foreach(int n in new[]{14,15})structuralColumn.Grid.Columns[n].Visible=false;structuralColumn.Grid.Columns[2].HeaderText="Column height m";structuralColumn.Grid.Columns[6].HeaderText="Main group 1 Ø mm";structuralColumn.Grid.Columns[7].HeaderText="Main group 1 bars / column";structuralColumn.Grid.Columns[10].HeaderText="Tie Ø mm";structuralColumn.Grid.Columns[8].HeaderText="Main group 2 Ø mm (optional)";structuralColumn.Grid.Columns[9].HeaderText="Main group 2 bars / column";
