  var clear=NewExtraGrid("Clearing","Clearing and Grubbing","Earthworks",new[]{"Area ID","Description / location","Length m","Width m","Qty","Input method","Direct total area m2","Clearing area m2","Status"},7,new Dictionary<int,string>{{4,"1"},{5,"Dimensions"}},"Use dimensions OR a directly measured total area. Direct area is the total for this row, without a second quantity multiplier. 800(1), square metres; enter non-overlapping areas only.");ExtraChoice(clear.Grid,5,"Dimensions","Direct total area");
  var tree=NewExtraGrid("Trees","Cutting of Trees","Earthworks",new[]{"Tree ID","Species / location (optional)","Measured diameter mm","Include?","Tree pay item","Tree quantity ea","Status"},4,new Dictionary<int,string>{{3,"True"}},"Tree IDs are assigned automatically. Every entered tree is included. Input diameter in mm at the approved measurement height. Pay-item bands: 150–300, >300–500, >500–750, >750–900, >900mm. Item 800(3)a2 corrected to 301–500mm per owner confirmation. Pay-item bands are assigned in the background.");ExtraCheck(tree.Grid,3);ConfigureAutomaticTrees(tree.Grid);
  string[] pavementNames={"Roadway Excavation","Subgrade Preparation","Aggregate Base / Subbase Course","PCCP 150 mm","PCCP 230 mm","Sidewalk"};
  for(int i=0;i<pavementNames.Length;i++){var item=NewExtraGrid("Pavement"+i,pavementNames[i],"Pavement Construction",new[]{"Entry ID","Description / location","Measured length m","Width m","Depth / thickness mm","Qty","Course / unit basis","Pay quantity","Pay unit","Reference concrete m3","Status"},7,new Dictionary<int,string>{{4,i==3?"150":i==4?"230":i==5?"100":"150"},{5,"1"},{6,i==2?"Aggregate Base Course":"Automatic"}},"Measured quantities only; use non-overlapping pavement areas. Roadway excavation and aggregate courses use volume. PCCP and sidewalk pay quantities use area; reference concrete volume is shown separately and is not added to the structural concrete BOQ. Subgrade preparation uses prepared area in square metres (length × width × quantity); no thickness input or swell/shrink factor is applied. Roadway excavation is in-place bank volume; swell/shrink factors apply separately to hauling/fill balance, not to this excavation quantity. For base course 201(1), add/map a matching BACKUP item if the workbook only contains subbase 200(1).");if(i==3||i==4){var heading=item.Grid.Parent.Controls.OfType<WorksheetHeading>().Single();heading.Text=BackupPayItemCatalog.Items().Single(t=>t.Code==(i==3?"311(1)a":"311(1)c1")).Description;heading.WrapTitle=true;heading.Height=90;}if(i==2)ExtraChoice(item.Grid,6,"Aggregate Base Course","Aggregate Subbase Course");else item.Grid.Columns[6].Visible=false;item.Grid.Columns[7].HeaderText=(i==1||i>=3)?"Total area (sq.m.)":"Total volume (cu.m.)";item.Grid.Columns[8].Visible=false;if(i==1)item.Grid.Columns[4].Visible=false;if(i>=3)item.Grid.Columns[4].ReadOnly=true;}
