 void AddExtraPanel(string key,string kind,string group,bool horizontal){var item=NewExtraGrid(key,kind,group,new[]{"Entry ID","Description / location",horizontal?"Length m":"Wall length m",horizontal?"Width / slope length m":"Height m","Thickness mm","Qty","Rebar layers (1/2)",horizontal?"X diameter mm":"Vertical diameter mm","First direction input method","First spacing mm / bar count",horizontal?"Y diameter mm":"Horizontal diameter mm","Second direction input method","Second spacing mm / bar count","First total end allowance mm","Second total end allowance mm",horizontal?"Long edges formed (0–2)":"Wall faces formed (0–2)",horizontal?"Short edges formed (0–2)":"Wall ends formed (0–2)",horizontal?"Soffit form?":"Bottom edge form?","Concrete m3","Formworks m2","Rebar NET kg","Rebar BUY kg","Status"},18,new Dictionary<int,string>{{4,horizontal?"100":"150"},{5,"1"},{6,"1"},{7,"10"},{8,"Spacing (mm)"},{9,"150"},{10,"10"},{11,"Spacing (mm)"},{12,"150"},{13,"0"},{14,"0"},{15,"2"},{16,horizontal?"2":"0"},{17,horizontal&&group=="Miscellaneous"?"True":"False"}},"Solid rectangular RC panels; use separate measured segments around openings. Select spacing OR number of bars independently in each direction, and one or two layers. Enter approved total end allowances. All layers are quantified. Slope length must be the actual inclined length, not its horizontal projection. Countertop edge forms and soffit are selected separately; parapet wall faces/ends/bottom are explicit. No structural design is inferred.");ExtraChoice(item.Grid,6,"1","2");ExtraChoice(item.Grid,8,"Spacing (mm)","Number of bars");ExtraChoice(item.Grid,11,"Spacing (mm)","Number of bars");ExtraCheck(item.Grid,17);}
