  Button(start,"Miscellaneous Structures settings",()=>{Commit();var names=MiscStructureTakeoff.Names;SettingsWorkspace.Show(this,"Miscellaneous Structures",names,names.Select(n=>(Control)extraMaterials[n].Panel).ToArray());Recalculate();});
  columnOpenHooks=SettingChoice(extraMaterials["Column Estimate"].Panel,"Open-tie end hooks",new[]{"Select hook angles","135° / 135°","90° / 135°"});columnOpenHooks.SelectedIndexChanged+=(s,e)=>{if(extraReady&&!filling)Recalculate();};
  Button(start,"Column settings",()=>SettingsWorkspace.Show(this,"Column",new[]{"Materials, cover and tie offsets"},new Control[]{extraMaterials["Column Estimate"].Panel}));
  foreach(var material in extraMaterials.Values)Button(material.Panel,"Commercial lengths",()=>{var values=StockLengthPicker.Choose(this,miscStock);if(values!=null){miscStock=values;Recalculate();}});
  start.Controls.Add(new Label{Text="Lean concrete thickness mm",AutoSize=true});leanThickness=new NumericUpDown{Minimum=1,Maximum=500,Value=50,DecimalPlaces=1,Width=100};leanThickness.ValueChanged+=(s,e)=>{if(extraReady&&!filling)Recalculate();};start.Controls.Add(leanThickness);Button(start,"Wall Footing settings",()=>SettingsWorkspace.Show(this,"Wall Footing",new[]{"Materials and cover"},new Control[]{extraMaterials["Wall Footing"].Panel}));
  var concrete=new FlowLayoutPanel{Width=1100,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(8)};concrete.Controls.Add(new Label{Text="CONCRETE PAY-ITEM ROUTING — checked = ready mix; unchecked = ordinary mix",AutoSize=true,Font=ModernUi.Strong});
  for(int i=0;i<ConcreteGroups.Length;i++){string key=ConcreteGroups[i];var box=new CheckBox{Text=ConcreteLabels[i]+" — Ready Mix",AutoSize=true,Margin=new Padding(3,5,3,5)};readyMixGroups.Add(key,box);box.CheckedChanged+=(s,e)=>{if(extraReady&&!filling){Recalculate();}};concrete.Controls.Add(box);}concrete.Controls.Add(new Label{Text="Groups with no matching ready-mix item in BACKUP remain unassigned; no ordinary-mix target is silently substituted.",AutoSize=true,MaximumSize=new Size(1050,0),ForeColor=PowTheme.Muted});start.Controls.Add(concrete);
  var earthStart=tabs.TabPages.Cast<TabPage>().Single(p=>p.Text=="Earthworks Start").Controls.OfType<FlowLayoutPanel>().Single();var options=new FlowLayoutPanel{AutoSize=true,Width=1100,Padding=new Padding(8)};excavationMaterial=SettingChoice(options,"Structural excavation material",new[]{"Common Soil","Soft Rock","Hard Rock"});subgradeUnit=new ComboBox();subgradeUnit.Items.Add("sq.m.");subgradeUnit.SelectedIndex=0;earthStart.Controls.Add(options);foreach(var box in new[]{excavationMaterial,subgradeUnit})box.SelectedIndexChanged+=(s,e)=>{if(extraReady&&!filling){Recalculate();}};
 }
 void LoadExtraDefaults(){if(!System.IO.File.Exists(RCDefaultStore.PathName))return;try{var doc=RCDefaultStore.Read(RCDefaultStore.PathName);if(doc!=null){bool before=filling;filling=true;try{ReadExtraSettings(doc.DocumentElement);}finally{filling=before;}}}catch(Exception ex){if(rcDefaultsStatus!=null)rcDefaultsStatus.Text="Extra settings defaults need review: "+ex.Message;}}
 LengthConfiguration ExtraConfiguration(string kind){var m=extraMaterials[kind];int small=int.Parse(m.Small.Text),large=int.Parse(m.Large.Text);return CalculationStore.Resolve(double.Parse(m.Fc.Text,CultureInfo.InvariantCulture),small,small==40?275:420,large,large==40?275:420);}
 void RecalculateExtraWorks(){miscQuantities.Clear();slopeQuantities.Clear();wallFootingResults.Clear();wallFootingPlan.Clear();leanSources.Clear();miscPlan.Clear();slopePlan.Clear();extraSiteQuantities.Clear();if(!extraReady)return;
  foreach(var item in extraGrids.Values.Where(x=>x.Group!="Carpentry and Joinery Works"&&x.Key!="Railing"&&x.Key!="SagRods")){var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(DataGridViewRow row in item.Grid.Rows){if(row.IsNewRow)continue;row.Tag=null;for(int i=item.Inputs;i<item.Grid.Columns.Count;i++)row.Cells[i].Value="";if(Empty(row))continue;try{
    if(item.Key=="Trees")AssignTreeIdentity(row);if(Cell(row,0)==""||!ids.Add(Cell(row,0)))throw new Exception("Enter a unique ID for this computation sheet.");
    if(item.Key=="WallFooting")RecalculateWallFooting(item,row);
    else if(item.Key.StartsWith("Misc")||item.Key=="StructuralColumn"||item.Key=="SlopeRCWall"||item.Key=="SlopeSlab"){
     var cfg=ExtraConfiguration(item.Kind);var settings=extraMaterials[item.Kind];MiscStructureQuantity q;
     if(item.Key=="StructuralColumn"&&Cell(row,8)!=""&&OptionalCount(row,9)==0)throw new Exception("Enter the bar quantity for Main group 2, or clear its unused diameter.");
     int scheduledSets=item.Key=="StructuralColumn"&&Cell(row,11)=="Spacing schedule"?ColumnTieSchedule.Count(Cell(row,12),Number(row,2),Number(row,3),Number(row,4),Count(row,10),(double)settings.Cover.Value,cfg):0;
     if(item.Inputs==16||item.Key=="StructuralColumn")q=MiscStructureTakeoff.Member(item.Kind,Cell(row,0),Cell(row,1),Number(row,2),Number(row,3),Number(row,4),Count(row,5),(double)settings.Cover.Value,Count(row,6),Count(row,7),OptionalCount(row,9)>0?Count(row,8):0,OptionalCount(row,9),Count(row,10),scheduledSets>0?"Number of ties":Cell(row,11),scheduledSets>0?scheduledSets:Number(row,12),(double)settings.Offset.Value,OptionalNumber(row,13),Cell(row,14)!=""&&bool.Parse(Cell(row,14)),OptionalCount(row,15),cfg);
     else q=MiscStructureTakeoff.Panel(item.Kind,Cell(row,0),Cell(row,1),Number(row,2),Number(row,3),Number(row,4),Count(row,5),(double)settings.Cover.Value,Count(row,6),MiscStructureTakeoff.Bars(Count(row,7),Cell(row,8),Number(row,9)),MiscStructureTakeoff.Bars(Count(row,10),Cell(row,11),Number(row,12)),OptionalNumber(row,13),OptionalNumber(row,14),int.Parse(Cell(row,15)),int.Parse(Cell(row,16)),Cell(row,17)!=""&&bool.Parse(Cell(row,17)),cfg);
     if(scheduledSets>0)q.Steel.Result.Lines.Find(l=>l.Part=="Stirrups").Formula+="; schedule = "+Cell(row,12)+"; main hoop counted once per station; open pieces entered separately.";
     if(item.Key=="StructuralColumn")ColumnOpenTies.Add(q,Number(row,3),Number(row,4),(double)settings.Cover.Value,Count(row,10),OptionalCount(row,16),OptionalCount(row,17),columnOpenHooks.Text,cfg);
     row.Tag=q;bool slope=item.Group=="Slope Protection Works";(slope?slopeQuantities:miscQuantities).Add(q);(slope?slopePlan:miscPlan).AddRange(CommercialBars.Allocate(new[]{q.Steel},cfg,miscStock));row.Cells[item.Inputs].Value=q.Concrete;row.Cells[item.Inputs+1].Value=q.Forms;row.Cells[item.Inputs+2].Value=q.Steel.Result.Total;row.Cells[item.Grid.Columns.Count-1].Value="Estimated";
    }else RecalculateSiteRow(item,row);
   }catch(Exception ex){row.Cells[item.Grid.Columns.Count-1].Value=ex.Message;errors.Add(item.Kind+" "+Cell(row,0)+": "+ex.Message);}}
  }
  RecalculateRailings();RecalculateSagRods();RecalculateCarpentry();ApplyExtraFoundationEarthworks();
 }
 void UpdateExtraPurchases(){if(!extraReady)return;UpdateWallFootingPurchase();foreach(var item in extraGrids.Values)foreach(DataGridViewRow row in item.Grid.Rows){var q=row.Tag as MiscStructureQuantity;if(q==null)continue;var plan=(item.Group=="Slope Protection Works"?slopePlan:miscPlan).Where(a=>a.Entry==q.Steel).ToList();row.Cells[item.Inputs+3].Value=plan.Sum(a=>a.Purchase);if(plan.Any(a=>a.Choice==null)){row.Cells[item.Grid.Columns.Count-1].Value="Unresolved commercial rebar cut";errors.Add(item.Kind+" "+q.Id+": unresolved stock cut.");}}if(projectRebarPlan.Any(a=>!slopePlan.Contains(a)&&a.Demand.Grade==60&&a.Demand.Diameter>42))errors.Add("Grade 60 bars above 42mm require an approved separate pay item.");}
 bool HasExtraInputs(){return extraGrids.Values.Any(x=>x.Grid.Rows.Cast<DataGridViewRow>().Any(r=>!r.IsNewRow&&!Empty(r)));}
 void CommitExtraInputs(){foreach(var item in extraGrids.Values)if(!item.Grid.EndEdit())throw new Exception("Correct the current "+item.Kind+" input.");}
 void AppendExtraWorksReport(StringBuilder b,bool detailed,string scope){b.AppendLine();b.AppendLine("ADDITIONAL QUANTITY TAKE-OFF | "+scope);bool all=scope=="Program of Works Summary",rc=all||scope=="Reinforced Concrete Works";foreach(var q in miscQuantities.Where(q=>rc).Concat(slopeQuantities.Where(q=>all||scope=="Slope Protection Works"))){b.AppendLine(q.Kind+" | "+q.Id+" | "+q.Description);b.AppendLine("Concrete = "+q.Concrete.ToString("0.########",CultureInfo.InvariantCulture)+"m3; forms = "+q.Forms.ToString("0.########",CultureInfo.InvariantCulture)+"m2; concrete "+q.Fc+"MPa");if(detailed){foreach(var line in q.Steel.Result.Lines)b.AppendLine(line.Part+" | G"+line.Grade+" D"+line.Diameter+" | "+line.Formula);PurchaseReports.Entry(b,(slopeQuantities.Contains(q)?slopePlan:miscPlan).Where(a=>a.Entry==q.Steel).ToList(),q.Quantity,reportDetail.SelectedIndex==2);}}foreach(var q in wallFootingResults.Where(q=>rc)){b.AppendLine("Wall footing "+q.Id+" | "+q.Description+" | concrete "+q.Concrete.ToString("R",CultureInfo.InvariantCulture)+"m3 | forms "+q.Forms.ToString("R",CultureInfo.InvariantCulture)+"m2 | excavation "+q.Excavation.ToString("R",CultureInfo.InvariantCulture)+"m3 | backfill "+q.Backfill.ToString("R",CultureInfo.InvariantCulture)+"m3");if(detailed)PurchaseReports.Entry(b,wallFootingPlan.Where(a=>a.Entry==q.Steel).ToList(),q.Quantity,reportDetail.SelectedIndex==2);}foreach(var q in leanSources.Where(q=>rc))b.AppendLine(q.Description+" | "+q.Quantity.ToString("R",CultureInfo.InvariantCulture)+"m3");foreach(var q in extraSiteQuantities.Where(q=>all||q.Section==scope||(scope=="Earthworks"&&q.Section=="Earthworks"))){b.AppendLine(q.Description+" | "+q.Quantity.ToString("0.########",CultureInfo.InvariantCulture)+" "+q.Unit);if(detailed)foreach(var source in q.Sources)b.AppendLine("  "+source.Description+" | "+source.Computation+" | "+source.Quantity.ToString("0.########",CultureInfo.InvariantCulture)+" "+source.Unit);}}
}
